struct StateComp {
    int resource_handle;
    bool operator()(int a, int b) const { return a < b; }
};

// Strong Exception Guarantee for std::swap(std::set) requires
// that the stateful comparator's swap operation is noexcept.
friend void swap(StateComp& a, StateComp& b) noexcept {
    // If this swap threw, the node pointers would roll back,
    // but the objects might be partially swapped (Basic Guarantee).
    std::swap(a.resource_handle, b.resource_handle);
}

std::set<int, StateComp> set_a;
std::set<int, StateComp> set_b;

// std::swap(set_a, set_b) is noexcept(true)
// because the tree root swap is atomic, AND
// the StateComp swap is marked noexcept.
